def transform(grid):
    g=[r[:] for r in grid]; H,W=len(g),len(g[0]); bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    seeds=[]
    for r in range(H):
        for c in range(W):
            x=g[r][c]
            if x in (0,bg): continue
            if not any(0<=rr<H and 0<=cc<W and g[rr][cc]==x for rr in range(r-1,r+2) for cc in range(c-1,c+2) if (rr,cc)!=(r,c)): seeds.append((r,c,x))
    for r,c,x in seeds:
        left=next((cc for cc in range(c-1,-1,-1) if g[r][cc]==0),None)
        right=next((cc for cc in range(c+1,W) if g[r][cc]==0),None)
        dl=c-left if left is not None else 999; dr=right-c if right is not None else 999
        side='L' if dl<dr else 'R'; wall=left if side=='L' else right; dist=min(dl,dr)
        up=next((rr for rr in range(r-1,-1,-1) if g[rr][c]==0),None)
        down=next((rr for rr in range(r+1,H) if g[rr][c]==0),None)
        du=r-up if up is not None else 999; dd=down-r if down is not None else 999
        direction='U' if du<=dd else 'D'
        def coords(direction):
            if dist==1: rows=(r-2,r-1) if direction=='U' else (r+1,r+2)
            else: rows=(r-3,r-2) if direction=='U' else (r+2,r+3)
            cols=(wall-1,wall) if side=='L' else (wall,wall+1)
            far=cols[0] if side=='L' else cols[-1]
            missing=(rows[0],far) if direction=='U' else (rows[1],far)
            ans=[(rr,cc) for rr in rows for cc in cols if (rr,cc)!=missing]
            if dist==2: ans.append((r-1 if direction=='U' else r+1,wall+1 if side=='L' else wall-1))
            return ans
        cells=coords(direction)
        if not all(0<=rr<H and 0<=cc<W for rr,cc in cells): cells=coords('U' if direction=='D' else 'D')
        for rr,cc in cells:
            if 0<=rr<H and 0<=cc<W: g[rr][cc]=x
    return g
